import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=name=>fileURLToPath(new URL(name,import.meta.url));
const call='_M0MPC15array5Array8containsGsE';
const checker=call+'(rule_ids, id)';
const rootSet='  const other_rule_count = p.rules.length - rule_ids.length | 0;';
for(const driver of ['lookupbench','deepbench']){
 const original=readFileSync(at('base-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
 assert.equal(original.split(checker).length,2);
 assert.equal(original.split(rootSet).length,2);
 for(const mode of ['counts','scan','timer-control']){
  const header="const stats={checks:0,rootComparisons:0,pathComparisons:0,peakLength:0,ms:0};\nconst rootSizes=new WeakMap();\n"+
  'function probe(ids,id){\n'+(mode==='counts'?
   '  const duplicate='+call+'(ids,id);\n  const scan=duplicate?ids.indexOf(id)+1:ids.length;\n'+
   '  const root=rootSizes.get(ids);\n  if(root===undefined||root>ids.length)throw new Error("missing root size");\n'+
   '  stats.checks++;stats.rootComparisons+=Math.min(root,scan);stats.pathComparisons+=Math.max(0,scan-root);\n'+
   '  stats.peakLength=Math.max(stats.peakLength,ids.length);\n  return duplicate;\n':
   mode==='scan'?
   '  const start=performance.now();\n  const found='+call+'(ids,id);\n  stats.ms+=performance.now()-start;\n  return found;\n':
   '  const start=performance.now();\n  stats.ms+=performance.now()-start;\n  return '+call+'(ids,id);\n')+
   "}\nprocess.once('exit',()=>console.error(JSON.stringify(stats)));\n";
  const code=original.replace(checker,'probe(rule_ids, id)');
  writeFileSync(at('base-'+driver+'-'+mode+'.js'),header+(mode==='counts'?code.replace(rootSet,'  rootSizes.set(rule_ids,rule_ids.length);\n'+rootSet):code));
 }
}
const rows=[];
for(const name of ['independent','first-pair','maintenance','four-resources','max-model','prefix-small','prefix-model','prefix-root','tight-impossible']){
 const deep=name==='tight-impossible';
 const run=mode=>{
  const args=[at('base-'+(deep?'deepbench':'lookupbench')+'-'+mode+'.js'),...(deep?[]:[name])];
  const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.ifError(r.error);
  assert.equal(r.status,0,r.stderr);
  assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(r.stderr);
 };
 const {ms,...counts}=run('counts');
 const phase={scan:[],'timer-control':[]};
 for(let i=0;i<3;i++)for(const mode of i%2?Object.keys(phase).reverse():Object.keys(phase))phase[mode].push(run(mode).ms);
 rows.push({name,counts,phase});
 console.log(name,JSON.stringify(counts),JSON.stringify(phase));
}
writeFileSync(at('baseline-probe.json'),JSON.stringify(rows,null,2)+'\n');

