import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=name=>fileURLToPath(new URL(name,import.meta.url));
const expected=JSON.parse(readFileSync(at('baseline-probe.json'),'utf8'));
const fn='_M0FP210JingLan0v03stn19append__order__rule';
const linear='_M0MPC15array5Array8containsGsE(rule_ids, id)';
const indexed=/_M0MPC17hashset7HashSet15add__and__checkGsE\((\w+), id\)/;
const rows={};
for(const variant of ['all','adaptive','reused']){
 const cases={};
 for(const driver of ['lookupbench','deepbench']){
  const source=readFileSync(at(variant+'-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
  const start=source.indexOf('function '+fn+'('), end=source.indexOf('\nfunction ',start+1);
  assert(start>=0&&end>start);
  const body=source.slice(start,end);
  assert(indexed.test(body));
  const changed=body.replace(indexed,'(counts.indexed++, $&)').replace(linear,'(counts.linear++, counts.comparisons+=rule_ids.length, '+linear+')');
  const program=at(variant+'-'+driver+'-count.js');
  writeFileSync(program,'const counts={indexed:0,linear:0,comparisons:0};\n'+
   "process.once('exit',()=>console.error(JSON.stringify(counts)));\n"+
   source.slice(0,start)+changed+source.slice(end));
  for(const trial of expected.filter(x=>(x.name==='tight-impossible')===(driver==='deepbench'))){
   const args=[program,...(driver==='deepbench'?[]:[trial.name])];
   const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
   assert.ifError(r.error);
   assert.equal(r.status,0,r.stderr);
   assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
   const c=JSON.parse(r.stderr);
   assert.equal(c.indexed+c.linear,trial.counts.checks);
   if(variant!=='adaptive'||trial.name==='prefix-model')assert.equal(c.indexed,trial.counts.checks);
   else if(trial.counts.peakLength<32)assert.equal(c.indexed,0);
   if(trial.name==='prefix-small'&&variant==='adaptive')assert.deepEqual(c,{indexed:42000,linear:96000,comparisons:2256000});
   cases[trial.name]=c;
  }
 }
 rows[variant]=cases;
 console.log(variant,JSON.stringify(Object.fromEntries(['max-model','prefix-model','prefix-small','tight-impossible'].map(n=>[n,cases[n]]))));
}
writeFileSync(at('variant-counts.json'),JSON.stringify(rows,null,2)+'\n');

